<?php
namespace Azuriom\Plugin\GamingHubCore\Services; use Azuriom\Plugin\GamingHubCore\Data\ExtensionManifest; use Azuriom\Plugin\GamingHubCore\Exceptions\UnsafeExtensionArchive; use ZipArchive;
final class ExtensionArchiveInspector { public function __construct(private ExtensionManifestValidator $manifests){} public function inspect(string $archive,string $extractTo):ExtensionManifest{$z=new ZipArchive();if($z->open($archive)!==true)throw new UnsafeExtensionArchive('Invalid ZIP archive.');$maxFiles=(int)config('gaming-hub-core.extensions.max_files',5000);if($z->numFiles<1||$z->numFiles>$maxFiles)throw new UnsafeExtensionArchive('Archive file-count limit exceeded.');$roots=[];$total=0;for($i=0;$i<$z->numFiles;$i++){$s=$z->statIndex($i);$name=str_replace('\\','/',$s['name']);if($name===''||str_starts_with($name,'/')||preg_match('#(^|/)\.\.(/|$)#',$name)||preg_match('/^[A-Za-z]:\//',$name))throw new UnsafeExtensionArchive('Unsafe archive path.');$parts=explode('/',$name);$roots[$parts[0]]=true;$total+=(int)($s['size']??0);$attr=(int)($s['external_attributes']??0);$mode=($attr>>16)&0170000;if($mode===0120000)throw new UnsafeExtensionArchive('Symlinks are not allowed.');if(preg_match('/\.(zip|tar|gz|phar)$/i',$name)&&count($parts)>1)throw new UnsafeExtensionArchive('Nested archives are not allowed.');}if(count($roots)!==1)throw new UnsafeExtensionArchive('Extension archive must contain exactly one root directory.');if($total>(int)config('gaming-hub-core.extensions.max_extracted_bytes',157286400))throw new UnsafeExtensionArchive('Extracted size limit exceeded.');$root=array_key_first($roots);foreach(['plugin.json','gaming-hub-extension.json'] as $required)if($z->locateName($root.'/'.$required)===false)throw new UnsafeExtensionArchive('Missing '.$required.'.');$plugin=json_decode($z->getFromName($root.'/plugin.json'),true);$manifest=json_decode($z->getFromName($root.'/gaming-hub-extension.json'),true);if(!is_array($plugin)||!is_array($manifest))throw new UnsafeExtensionArchive('Invalid package metadata JSON.');$m=$this->manifests->validate($manifest,$plugin);if($root!==$m->pluginDirectory)throw new UnsafeExtensionArchive('Archive root does not match plugin_directory.');if(is_dir($extractTo))$this->delete($extractTo);mkdir($extractTo,0755,true);if(!$z->extractTo($extractTo))throw new UnsafeExtensionArchive('Unable to extract archive.');$z->close();return $m;} private function delete(string $p):void{foreach(new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($p,\FilesystemIterator::SKIP_DOTS),\RecursiveIteratorIterator::CHILD_FIRST) as $f){$f->isDir()?rmdir($f->getPathname()):unlink($f->getPathname());}rmdir($p);}}
